#pragma once

#include <array>
#include <cstddef>
#include <cstdint>

namespace autoclicker {

// A platform-independent state machine using the Windows virtual-key values.
// Alt and C are the prefix: P/S must be pressed AFTER both prefix keys.
// No action is generated by seeding, key-up, or an auto-repeated key-down.
class ChordState final {
public:
    enum class Action { None, Start, Stop };

    struct Result {
        Action action = Action::None;
        bool suppress = false;
    };

    static constexpr std::uint32_t Shift = 0x10;
    static constexpr std::uint32_t Control = 0x11;
    static constexpr std::uint32_t Alt = 0x12;
    static constexpr std::uint32_t C = 0x43;
    static constexpr std::uint32_t P = 0x50;
    static constexpr std::uint32_t S = 0x53;
    static constexpr std::uint32_t LeftWin = 0x5B;
    static constexpr std::uint32_t RightWin = 0x5C;
    static constexpr std::uint32_t LeftShift = 0xA0;
    static constexpr std::uint32_t RightShift = 0xA1;
    static constexpr std::uint32_t LeftControl = 0xA2;
    static constexpr std::uint32_t RightControl = 0xA3;
    static constexpr std::uint32_t LeftAlt = 0xA4;
    static constexpr std::uint32_t RightAlt = 0xA5;

    void Reset() noexcept
    {
        pressed_.fill(false);
        suppressed_.fill(false);
    }

    // Seed only physical left/right modifiers when using this with Windows.
    // Seeding generic AND left/right modifier keys would leave the generic
    // key stuck because low-level hooks report physical modifier releases.
    void SeedPressed(std::uint32_t key) noexcept
    {
        if (key < pressed_.size()) {
            pressed_[key] = true;
        }
    }

    Result Process(std::uint32_t key, bool down) noexcept
    {
        if (key >= pressed_.size()) {
            return {};
        }

        const bool wasDown = pressed_[key];
        pressed_[key] = down;

        if (!down) {
            const bool consume = suppressed_[key];
            suppressed_[key] = false;
            return { Action::None, consume };
        }

        if (wasDown) {
            return { Action::None, suppressed_[key] };
        }

        if ((key != P && key != S) || !PrefixHeld() || ExtraModifierHeld()) {
            return {};
        }

        // Stop wins when both terminal keys are held. In particular, releasing
        // S while P remains down cannot restart: it needs a NEW P key-down.
        const Action action = pressed_[S] ? Action::Stop : Action::Start;
        suppressed_[key] = true;
        return { action, true };
    }

    // If delivery to the owner window fails, pass the terminal key through,
    // including subsequent repeats and its eventual key-up.
    void CancelSuppression(std::uint32_t key) noexcept
    {
        if (key < suppressed_.size()) {
            suppressed_[key] = false;
        }
    }

private:
    bool PrefixHeld() const noexcept
    {
        return pressed_[C] && (pressed_[Alt] || pressed_[LeftAlt] || pressed_[RightAlt]);
    }

    bool ExtraModifierHeld() const noexcept
    {
        return pressed_[Shift] || pressed_[LeftShift] || pressed_[RightShift]
            || pressed_[Control] || pressed_[LeftControl] || pressed_[RightControl]
            || pressed_[LeftWin] || pressed_[RightWin];
    }

    std::array<bool, 256> pressed_{};
    std::array<bool, 256> suppressed_{};
};

} // namespace autoclicker
